window.READING_TESTS[9]={"id": 9, "module": "reading", "vol": 9, "sections": [{"number": 1, "html": "<p class=\"subheading\">Questions 1–7</p><p class=\"instruction\"><i>Choose </i><i><b>TRUE</b></i><i> if the statement agrees with the information given in the text, choose </i><i><b>FALSE</b></i><i> if the statement contradicts the information, or choose </i><i><b>NOT GIVEN</b></i><i> if there is no information on this.</i></p><div data-render-choice=\"1\"></div><div data-render-choice=\"2\"></div><div data-render-choice=\"3\"></div><div data-render-choice=\"4\"></div><div data-render-choice=\"5\"></div><div data-render-choice=\"6\"></div><div data-render-choice=\"7\"></div>\n<p class=\"subheading\">Questions 8–13</p><p class=\"instruction\">Complete the notes below.</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> for each answer.</p><p class=\"\"><b>The Cycle of Cranberry Production</b></p><p><b>Winter</b>Growers <span class=\"qnum\">8</span><input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\">  the bogs to protect vines.Sand is put on bogs to increase <span class=\"qnum\">9</span><input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\">  and encourage growth.Trees are removed to promote the movement of  <span class=\"qnum\">10</span><input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\"> <b>Spring</b><span class=\"qnum\">11</span><input class=\"gap\" data-q=\"11\" aria-label=\"Câu 11\" autocomplete=\"off\" spellcheck=\"false\"> is supplied to protect against frost.<span class=\"qnum\">12</span><input class=\"gap\" data-q=\"12\" aria-label=\"Câu 12\" autocomplete=\"off\" spellcheck=\"false\"> is done to control pests.<b>Summer</b>Growers check for  <span class=\"qnum\">13</span><input class=\"gap\" data-q=\"13\" aria-label=\"Câu 13\" autocomplete=\"off\" spellcheck=\"false\">  growth.</p>"}, {"number": 2, "html": "<p class=\"subheading\">Questions 14–18</p><p class=\"instruction\">Reading Passage 2 has seven paragraphs, <b>A–G.</b></p><p class=\"instruction\"><i>Which paragraph contains the following information?</i></p><p class=\"instruction\">Choose the correct letter, <b>A–G</b>.</p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> A</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> B</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> C</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> D</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> E</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> F</button><button class=\"token\" draggable=\"true\" data-token=\"G\"><b>G</b> G</button></div><p class=\"matching-row\" data-drop=\"14\"><span class=\"qnum\">14</span>a description of different kinds of cocoa used in chocolate production <select class=\"answer-select\" data-q=\"14\" aria-label=\"Câu 14\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"15\"><span class=\"qnum\">15</span>an explanation that chemicals produced during cocoa digestion may reduce the risks of diseases <select class=\"answer-select\" data-q=\"15\" aria-label=\"Câu 15\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"16\"><span class=\"qnum\">16</span>a reference to a group of people who may not benefit from eating chocolate <select class=\"answer-select\" data-q=\"16\" aria-label=\"Câu 16\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"17\"><span class=\"qnum\">17</span>an example of a specific way cocoa can be added into beverage <select class=\"answer-select\" data-q=\"17\" aria-label=\"Câu 17\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p><p class=\"matching-row\" data-drop=\"18\"><span class=\"qnum\">18</span>information about differences in the way people digest cocoa <select class=\"answer-select\" data-q=\"18\" aria-label=\"Câu 18\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option></select></p>\n<p class=\"subheading\">Questions 19–22</p><p class=\"instruction\">Look at the following statements and the list of people or organizations below.</p><p class=\"instruction\">Match each statement with the correct person or organization,<b> A–D</b>.</p><p class=\"instruction\"><b>List of people or organizations</b></p><p class=\"instruction\"><b>A</b>    Ginger Hultin</p><p class=\"instruction\"><b>B</b>    European Food Safety Authority</p><p class=\"instruction\"><b>C    </b>Howard Sesso</p><p class=\"instruction\"><b>D</b>    EPIC-Norfolk</p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> Ginger Hultin</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> European Food Safety Authority</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> Howard Sesso</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> EPIC-Norfolk</button></div><p class=\"matching-row\" data-drop=\"19\"><span class=\"qnum\">19</span>Eating cocoa together with dietary fiber may improve health. <select class=\"answer-select\" data-q=\"19\" aria-label=\"Câu 19\"><option value=\"\">Chọn</option><option value=\"A\">A · Ginger Hultin</option><option value=\"B\">B · European Food Safety Authority</option><option value=\"C\">C · Howard Sesso</option><option value=\"D\">D · EPIC-Norfolk</option></select></p><p class=\"matching-row\" data-drop=\"20\"><span class=\"qnum\">20</span>Dark chocolate consumption could reduce medical spending in the future. <select class=\"answer-select\" data-q=\"20\" aria-label=\"Câu 20\"><option value=\"\">Chọn</option><option value=\"A\">A · Ginger Hultin</option><option value=\"B\">B · European Food Safety Authority</option><option value=\"C\">C · Howard Sesso</option><option value=\"D\">D · EPIC-Norfolk</option></select></p><p class=\"matching-row\" data-drop=\"21\"><span class=\"qnum\">21</span>Dark chocolate should not be considered a replacement for medicine. <select class=\"answer-select\" data-q=\"21\" aria-label=\"Câu 21\"><option value=\"\">Chọn</option><option value=\"A\">A · Ginger Hultin</option><option value=\"B\">B · European Food Safety Authority</option><option value=\"C\">C · Howard Sesso</option><option value=\"D\">D · EPIC-Norfolk</option></select></p><p class=\"matching-row\" data-drop=\"22\"><span class=\"qnum\">22</span>The amount of cocoa required for health benefits remains uncertain. <select class=\"answer-select\" data-q=\"22\" aria-label=\"Câu 22\"><option value=\"\">Chọn</option><option value=\"A\">A · Ginger Hultin</option><option value=\"B\">B · European Food Safety Authority</option><option value=\"C\">C · Howard Sesso</option><option value=\"D\">D · EPIC-Norfolk</option></select></p>\n<p class=\"subheading\">Questions 23–26</p><p class=\"instruction\">Complete the sentences below.</p><p class=\"instruction\">Write<b> ONE WORD ONLY</b> from the passage for each answer.</p><p>The digestive process turns cocoa into less complex chemical <span class=\"qnum\">23</span><input class=\"gap\" data-q=\"23\" aria-label=\"Câu 23\" autocomplete=\"off\" spellcheck=\"false\"></p><p>The <span class=\"qnum\">24</span><input class=\"gap\" data-q=\"24\" aria-label=\"Câu 24\" autocomplete=\"off\" spellcheck=\"false\">  would vary according to chocolate type with dark chocolate outperforming milk chocolate.</p><p>Dark chocolate should not be regarded as healthy due to its richness of calories and <span class=\"qnum\">25</span><input class=\"gap\" data-q=\"25\" aria-label=\"Câu 25\" autocomplete=\"off\" spellcheck=\"false\"></p><p>In Hultin’s view, dietary diversity is the best strategy for acquiring <span class=\"qnum\">26</span><input class=\"gap\" data-q=\"26\" aria-label=\"Câu 26\" autocomplete=\"off\" spellcheck=\"false\"></p>"}, {"number": 3, "html": "<p class=\"subheading\">Questions 27–30</p><p class=\"instruction\"><i>Choose </i><i><b>YES</b></i><i> if the statement agrees with the claims of the writer, choose </i><i><b>NO</b></i><i> if the statement contradicts the claims of the writer, or </i><i><b>NOT GIVEN</b></i><i> if it is impossible to say what the writer thinks about this.</i></p><div data-render-choice=\"27\"></div><div data-render-choice=\"28\"></div><div data-render-choice=\"29\"></div><div data-render-choice=\"30\"></div>\n<p class=\"subheading\">Questions 31–34</p><p class=\"instruction\">Choose the correct answer.</p><div data-render-choice=\"31\"></div><div data-render-choice=\"32\"></div><div data-render-choice=\"33\"></div><div data-render-choice=\"34\"></div>\n<p class=\"subheading\">Questions 35–40</p><p class=\"instruction\">Complete the summary using the list of words, <b>A-K</b>, below.</p><p class=\"instruction\">Choose the correct letter, <b>A-K</b>, in boxes <b>35-40</b>.</p><p class=\"\"><b>A</b> parental love<b>B</b> imaginative games<b>C</b> physical development</p><p class=\"\"><b>D</b> generous behaviour<b>E</b> strong marriages<b>F </b>greater individuality</p><p class=\"\"><b>G </b>learning experiences<b>H</b> career success<b>I</b> closer relationships</p><p class=\"\"><b>J</b> healthy competition <b>K</b> mental well-being</p><p class=\"\"><b>The positive aspects of sibling relationships</b></p><p>Annette Henderson suggests that young children&#x27;s interactions with older siblings involve <span class=\"inline-match\" data-drop=\"35\"><span class=\"qnum\">35</span><select class=\"answer-select\" data-q=\"35\" aria-label=\"Câu 35\"><option value=\"\">Chọn</option><option value=\"A\">A · parental love</option><option value=\"B\">B · imaginative games</option><option value=\"C\">C · physical development</option><option value=\"D\">D · generous behaviour</option><option value=\"E\">E · strong marriages</option><option value=\"F\">F · greater individuality</option><option value=\"G\">G · learning experiences</option><option value=\"H\">H · career success</option><option value=\"I\">I · closer relationships</option><option value=\"J\">J · healthy competition</option><option value=\"K\">K · mental well-being</option></select></span> Also, a Cambridge study found that siblings still enjoy <span class=\"inline-match\" data-drop=\"36\"><span class=\"qnum\">36</span><select class=\"answer-select\" data-q=\"36\" aria-label=\"Câu 36\"><option value=\"\">Chọn</option><option value=\"A\">A · parental love</option><option value=\"B\">B · imaginative games</option><option value=\"C\">C · physical development</option><option value=\"D\">D · generous behaviour</option><option value=\"E\">E · strong marriages</option><option value=\"F\">F · greater individuality</option><option value=\"G\">G · learning experiences</option><option value=\"H\">H · career success</option><option value=\"I\">I · closer relationships</option><option value=\"J\">J · healthy competition</option><option value=\"K\">K · mental well-being</option></select></span> even when they have a tendency to fight. Research conducted in 2003 suggests that children develop <span class=\"inline-match\" data-drop=\"37\"><span class=\"qnum\">37</span><select class=\"answer-select\" data-q=\"37\" aria-label=\"Câu 37\"><option value=\"\">Chọn</option><option value=\"A\">A · parental love</option><option value=\"B\">B · imaginative games</option><option value=\"C\">C · physical development</option><option value=\"D\">D · generous behaviour</option><option value=\"E\">E · strong marriages</option><option value=\"F\">F · greater individuality</option><option value=\"G\">G · learning experiences</option><option value=\"H\">H · career success</option><option value=\"I\">I · closer relationships</option><option value=\"J\">J · healthy competition</option><option value=\"K\">K · mental well-being</option></select></span> as a result of seeking attention. Another factor is the trend for smaller families, which may mean that today&#x27;s siblings enjoy <span class=\"inline-match\" data-drop=\"38\"><span class=\"qnum\">38</span><select class=\"answer-select\" data-q=\"38\" aria-label=\"Câu 38\"><option value=\"\">Chọn</option><option value=\"A\">A · parental love</option><option value=\"B\">B · imaginative games</option><option value=\"C\">C · physical development</option><option value=\"D\">D · generous behaviour</option><option value=\"E\">E · strong marriages</option><option value=\"F\">F · greater individuality</option><option value=\"G\">G · learning experiences</option><option value=\"H\">H · career success</option><option value=\"I\">I · closer relationships</option><option value=\"J\">J · healthy competition</option><option value=\"K\">K · mental well-being</option></select></span> as adults. A 2010 American study linked having a sister with <span class=\"inline-match\" data-drop=\"39\"><span class=\"qnum\">39</span><select class=\"answer-select\" data-q=\"39\" aria-label=\"Câu 39\"><option value=\"\">Chọn</option><option value=\"A\">A · parental love</option><option value=\"B\">B · imaginative games</option><option value=\"C\">C · physical development</option><option value=\"D\">D · generous behaviour</option><option value=\"E\">E · strong marriages</option><option value=\"F\">F · greater individuality</option><option value=\"G\">G · learning experiences</option><option value=\"H\">H · career success</option><option value=\"I\">I · closer relationships</option><option value=\"J\">J · healthy competition</option><option value=\"K\">K · mental well-being</option></select></span> among children aged 10-14. Finally, having a sibling may promote <span class=\"inline-match\" data-drop=\"40\"><span class=\"qnum\">40</span><select class=\"answer-select\" data-q=\"40\" aria-label=\"Câu 40\"><option value=\"\">Chọn</option><option value=\"A\">A · parental love</option><option value=\"B\">B · imaginative games</option><option value=\"C\">C · physical development</option><option value=\"D\">D · generous behaviour</option><option value=\"E\">E · strong marriages</option><option value=\"F\">F · greater individuality</option><option value=\"G\">G · learning experiences</option><option value=\"H\">H · career success</option><option value=\"I\">I · closer relationships</option><option value=\"J\">J · healthy competition</option><option value=\"K\">K · mental well-being</option></select></span><b> </b>according to the same study.</p>"}], "passages": [{"number": 1, "title": "Cranberry Fruit", "subtitle": "<i>The story of a unique North American crop</i>"}, {"number": 2, "title": "Dark Chocolate’s Health-giving Benefits", "subtitle": "<i>Researchers are investigating whether taking dark chocolate daily can reduce the risk of heart disease and stroke</i>"}, {"number": 3, "title": "All in the family", "subtitle": "<i>A person&#x27;s brothers and sisters can have a powerful effect on their adult behaviour</i>"}], "singles": [{"n": 1, "prompt": "The cranberry requires a specific soil type to enable it to grow successfully.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 2, "prompt": "A layer of clay protects kettle ponds from harmful substances which could affect the water quality.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 3, "prompt": "In the past, the Wampanoag people had to consume most cranberries shortly after picking them.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 4, "prompt": "The Wampanoag people took advantage of the medicinal properties of cranberries.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 5, "prompt": "The first settlers in North America brought European varieties of cranberry with them when they arrived.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 6, "prompt": "Captain Hall tried growing other fruit crops before cultivating cranberries.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 7, "prompt": "It took a long time for Captain Hall’s methods of cultivation to become popular among other cranberry producers.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 27, "prompt": "Parents and siblings play equal roles in shaping people's adult personalities.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 28, "prompt": "People's first social relationships tend to be with siblings of their own gender.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 29, "prompt": "People's relationships with their siblings tend to receive less attention when they marry.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 30, "prompt": "Parental 'basking' is advantageous for later siblings.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 31, "prompt": "What point does the writer make about birth order in the third paragraph?", "options": ["Its role is underestimated by parents.", "It may shape the characteristics of adults.", "Its importance decreases as children grow up.", "It has more influence on personality than genetics."]}, {"n": 32, "prompt": "What are we told about some of Claire Cartwright's clients?", "options": ["Their parents treated them fairly.", "They were treated harshly by their siblings.", "Their perceptions of childhood may be inaccurate.", "They have closer relations with their siblings as adults."]}, {"n": 33, "prompt": "What is the writer's main point about siblings in the fifth paragraph?", "options": ["Parents tend to repeat their own parents' mistakes.", "Favored children are likely to make good leaders as adults.", "Negative characteristics in children can become positive in adults.", "Attention-seeking children are unlikely to please bosses in later life."]}, {"n": 34, "prompt": "Which of the following best summarises the writer's argument in the sixth paragraph?", "options": ["Many children have a favourite parent.", "Parenting skills improve with later children.", "Siblings are born with different personalities.", "The family environment may change over time."]}], "pairs": [], "answers": {"1": ["TRUE"], "2": ["TRUE"], "3": ["FALSE"], "4": ["TRUE"], "5": ["NOT GIVEN"], "6": ["NOT GIVEN"], "7": ["NOT GIVEN"], "8": ["flood"], "9": ["drainage"], "10": ["air"], "11": ["water"], "12": ["maintenance"], "13": ["weed"], "14": ["F"], "15": ["B"], "16": ["E"], "17": ["G"], "18": ["C"], "19": ["A"], "20": ["B"], "21": ["D"], "22": ["C"], "23": ["compounds"], "24": ["benefits"], "25": ["fats"], "26": ["fiber"], "27": ["NO"], "28": ["NOT GIVEN"], "29": ["NOT GIVEN"], "30": ["YES"], "31": ["B"], "32": ["C"], "33": ["C"], "34": ["D"], "35": ["G"], "36": ["B"], "37": ["F"], "38": ["I"], "39": ["K"], "40": ["D"]}, "explanations": {"1": "<p>1 TRUE</p><p>Câu hỏi: <i>The cranberry requires a specific soil type to enable it to grow successfully.</i></p><p>(Nam việt quất cần một loại đất đặc biệt để có thể phát triển tốt.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: These small, crimson berries thrive only in very unique environmental conditions, particularly in soil that is both sandy and acidic.</p><p>(Những quả nhỏ màu đỏ này chỉ phát triển tốt trong điều kiện môi trường rất đặc biệt, đặc biệt là ở loại đất vừa cát vừa có tính axit.)</p>", "2": "<p>2 TRUE</p><p>Câu hỏi: <i>A layer of clay protects kettle ponds from harmful substances which could affect the water quality.</i></p><p>(Một lớp đất sét bảo vệ các hồ kettle khỏi các chất có hại có thể ảnh hưởng đến chất lượng nước.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The clay bottom acts as a protective barrier, preventing harmful substances from entering the pond and preserving the clean water essential for healthy vines.  </p><p>(Lớp đất sét dưới đáy hoạt động như một hàng rào bảo vệ, ngăn các chất có hại xâm nhập vào hồ và giữ cho nguồn nước luôn sạch - điều rất cần thiết để cây nam việt quất phát triển khỏe mạnh.)</p>", "3": "<p>3 FALSE</p><p>Câu hỏi: <i>In the past, the Wampanoag people had to consume most cranberries shortly after picking them.</i></p><p>( Trước đây người Wampanoag phải ăn phần lớn nam việt quất ngay sau khi hái.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: communities developed methods of drying and combining cranberries with other foods to extend their usefulness during months when fresh plants were scarce.</p><p>(Các cộng đồng đã phát triển cách phơi khô và kết hợp nam việt quất với thực phẩm khác để dùng được lâu hơn trong những tháng khan hiếm cây tươi.)</p><p>Giải thích: Đề nói họ phải ăn ngay sau khi hái. Bài nói họ bảo quản để dùng lâu dài → trái ngược.</p>", "4": "<p>4 TRUE</p><p>Câu hỏi: <i>The Wampanoag people took advantage of the medicinal properties of cranberries.</i></p><p>(Người Wampanoag đã tận dụng đặc tính chữa bệnh của nam việt quất.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In addition to dietary uses, the Wampanoag also employed the berry in first-aid traditions: crushed fruit was applied to sores and minor wounds, reflecting a practical knowledge of its cleansing properties.</p><p>(Ngoài việc dùng làm thực phẩm, người Wampanoag còn sử dụng loại quả này trong các phương pháp sơ cứu truyền thống: quả được nghiền nát rồi đắp lên các vết loét và vết thương nhỏ, cho thấy họ hiểu rõ và vận dụng được đặc tính làm sạch của nó.)</p>", "5": "<p>5 NOT GIVEN</p><p>Câu hỏi: <i>The first settlers in North America brought European varieties of cranberry with them when they arrived.</i></p><p>( Những người định cư đầu tiên ở Bắc Mỹ đã mang theo giống nam việt quất châu Âu khi họ đến.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Rather than attempting to transplant European varieties, the newcomers adopted the native species already adapted to regional conditions.</p><p>(Thay vì cố gắng đem các giống châu Âu sang trồng lại, những người mới đến đã sử dụng giống bản địa vốn đã thích nghi sẵn với điều kiện của khu vực)</p><p>Giải thích: Tuy nhiên không hề có thông tin cho biết là khi di cư họ có mang theo giống từ châu Âu không, hay là đến nơi họ mới phát hiện quả cranberry bản địa.</p>", "6": "<p>6 NOT GIVEN</p><p>Câu hỏi: <i>Captain Hall tried growing other fruit crops before cultivating cranberries.</i></p><p>(Thuyền trưởng Hall đã thử trồng các loại trái cây khác trước khi trồng nam việt quất.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: One Massachusetts grower, Captain Henry Hall, observed that windblown sand reaching his beds improved fruit quality and yield.</p><p>(Một người trồng ở Massachusetts, Captain Henry Hall, nhận thấy cát do gió thổi vào luống giúp cải thiện chất lượng và năng suất.)</p><p>Giải thích: Không có thông tin ông ấy từng trồng loại quả khác trước đó.</p>", "7": "<p>7 NOT GIVEN</p><p>Câu hỏi:<i> It took a long time for Captain Hall’s methods of cultivation to become popular among other cranberry producers.</i></p><p>( Phải mất một thời gian dài thì phương pháp canh tác của Hall mới trở nên phổ biến với những người trồng nam việt quất khác.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Hall’s practice of controlling the land and surface materials was an important step toward systematic cranberry farming.</p><p>(Phương pháp kiểm soát đất và lớp vật liệu bề mặt của Hall là một bước quan trọng hướng tới việc canh tác nam việt quất có hệ thống.)</p><p>Giải thích: Bài không nói mất bao lâu hoặc người khác áp dụng khi nào.</p>", "8": "<p>8 flood</p><p>Câu hỏi: <i>Growers ______ the bogs to protect vines.</i></p><p>(Người trồng ______ các đầm lầy để bảo vệ cây nam việt quất.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In winter farmers often choose to flood the bogs, forming a protective layer that freezes and insulates the vines from extreme cold and drying winds.</p><p>(Vào mùa đông, nông dân thường cho ngập nước các đầm lầy, tạo nên một lớp bảo vệ đóng băng giúp cách ly cây khỏi cái lạnh khắc nghiệt và những cơn gió khô.)</p>", "9": "<p>9 drainage</p><p>Câu hỏi: <i>Sand is put on bogs to increase ______ and encourage growth.</i></p><p>(Cát được rải lên đầm để tăng ______ và thúc đẩy cây phát triển.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: On the frozen surface, sand is sometimes scattered so that, when thawed, the particles work into the bed and improve overall drainage, encouraging fresh shoots to establish.</p><p>(Trên bề mặt đã đóng băng, đôi khi cát được rải lên để khi băng tan, các hạt cát ngấm xuống lớp đất bên dưới và cải thiện khả năng thoát nước tổng thể, từ đó giúp các chồi non phát triển.)</p>", "10": "<p>10 air</p><p>Câu hỏi: <i>Trees are removed to promote the movement of ______.</i></p><p>(Cây được dọn đi để giúp ______ lưu thông tốt hơn.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: To reduce disease risk and improve crop vigour, farmers also remove trees and scrub beside the bogs so that air can move through the site more freely and humidity is kept low.</p><p>(Để giảm nguy cơ sâu bệnh và giúp cây khỏe hơn, nông dân cũng dọn cây và bụi rậm bên cạnh đầm để không khí lưu thông tự do hơn và giữ độ ẩm ở mức thấp.)</p>", "11": "<p>11 water</p><p>Câu hỏi: <i>______ is supplied to protect against frost.</i></p><p>(______ được cung cấp để bảo vệ khỏi sương giá.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: With the coming of spring, the frozen cover is managed and water levels are adjusted; controlled water applications may be used at vulnerable times to shield budding shoots from sudden frosts.</p><p>(Khi mùa xuân đến, lớp băng được kiểm soát và mực nước được điều chỉnh; nước được cung cấp có kiểm soát vào những thời điểm cây dễ bị ảnh hưởng để bảo vệ các chồi non khỏi những đợt sương giá bất ngờ.)</p>", "12": "<p>12 maintenance</p><p>Câu hỏi:<i> ______ is done to control pests.</i></p><p>(Việc ______ được thực hiện để kiểm soát sâu bệnh.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: During this phase growers perform routine maintenance on channels, pumps and irrigation lines and take steps to reduce pest pressure before the plants enter full growth.</p><p>(Trong giai đoạn này, người trồng thực hiện bảo trì định kỳ đối với các kênh dẫn nước, máy bơm và hệ thống tưới tiêu, đồng thời tiến hành các biện pháp nhằm giảm áp lực sâu bệnh trước khi cây bước vào giai đoạn phát triển mạnh.)</p>", "13": "<p>13 weed</p><p>Câu hỏi: <i>Growers check for ______ growth.</i></p><p>(Người trồng kiểm tra sự phát triển của ______.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Farmers inspect beds for any sign of weed emergence that would compete with the crop for nutrients and light, removing intruders promptly to protect potential yields.</p><p>(Nông dân kiểm tra các luống trồng để tìm bất kỳ dấu hiệu nào của cỏ dại mọc lên - vì chúng sẽ cạnh tranh chất dinh dưỡng và ánh sáng với cây trồng - rồi nhanh chóng loại bỏ để bảo vệ năng suất tiềm năng.)</p>", "14": "<p>14 F</p><p>Câu hỏi: <i>a description of different kinds of cocoa used in chocolate production</i></p><p>(mô tả các loại ca cao khác nhau được dùng trong sản xuất sô-cô-la)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Cocoa may also appear in the form of cocoa powder, cocoa butter, or concentrated cocoa extracts.</p><p>(Ca cao cũng có thể xuất hiện dưới dạng bột ca cao, bơ ca cao, hoặc chiết xuất ca cao cô đặc.)</p>", "15": "<p>15 B</p><p>Câu hỏi: <i>an explanation that chemicals produced during cocoa digestion may reduce the risks of diseases</i></p><p>(giải thích rằng các chất hóa học tạo ra trong quá trình tiêu hóa ca cao có thể làm giảm nguy cơ bệnh tật)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: During digestion, cocoa is broken down into smaller chemical compounds. Some research suggests that these compounds have anti-inflammatory and antioxidant properties and may help protect against cardiovascular disease, which affects both the heart and brain.</p><p>(Trong quá trình tiêu hóa, ca cao được phân giải thành những hợp chất hóa học nhỏ hơn. Một số nghiên cứu cho thấy những hợp chất này có đặc tính chống viêm và chống oxy hóa, đồng thời có thể giúp bảo vệ cơ thể khỏi bệnh tim mạch, loại bệnh ảnh hưởng đến cả tim và não.)</p>", "16": "<p>16 E</p><p>Câu hỏi: <i>a reference to a group of people who may not benefit from eating chocolate</i></p><p>(nhắc đến một nhóm người có thể không nhận được lợi ích từ việc ăn sô-cô-la)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The research also suggested that certain groups, particularly overweight individuals, may not receive the same protective effects from chocolate consumption as younger and normal-weight men</p><p>(Nghiên cứu cũng cho thấy rằng một số nhóm người nhất định, đặc biệt là những người thừa cân, có thể không nhận được cùng mức tác dụng bảo vệ từ việc tiêu thụ sô-cô-la như nam giới trẻ tuổi và có cân nặng bình thường.)</p>", "17": "<p>17 G</p><p>Câu hỏi: <i>an example of a specific way cocoa can be added into beverage</i></p><p>(ví dụ cụ thể về cách thêm ca cao vào đồ uống)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: ‘I put cocoa powder in my smoothies for an added boost of flavor, nutrients and antioxidants.’</p><p>(“Tôi cho bột ca cao vào sinh tố để tăng thêm hương vị, dưỡng chất và chất chống oxy hóa.”)</p>", "18": "<p>18 C</p><p>Câu hỏi: <i>information about differences in the way people digest cocoa</i></p><p>(thông tin về sự khác nhau trong cách con người tiêu hóa ca cao)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Researchers have also pointed out that people may digest cocoa differently. Variations in gut bacteria can influence how flavanols are processed and absorbed in the body. As a result, the health effects of cocoa may differ from person to person, depending on individual digestive systems and dietary habits.</p><p>(Các nhà nghiên cứu cũng chỉ ra rằng mọi người có thể tiêu hóa ca cao theo những cách khác nhau. Sự khác biệt trong vi khuẩn đường ruột có thể ảnh hưởng đến cách các flavanol được xử lý và hấp thụ trong cơ thể. Vì vậy, tác động của ca cao đối với sức khỏe có thể khác nhau tùy từng người, phụ thuộc vào hệ tiêu hóa cá nhân và thói quen ăn uống của mỗi người.)</p>", "19": "<p>19 A</p><p>Câu hỏi: <i>Eating cocoa together with dietary fiber may improve health.</i></p><p>(Ăn ca cao cùng với chất xơ có thể cải thiện sức khỏe.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: ‘We get different phytochemicals and antioxidants from a wide variety of foods,’ Hultin says. ‘Including different colors of fruits, vegetables, whole grains and beans is the best way to gain access to fiber that could support health.’</p><p>(Hultin nói: “Chúng ta hấp thụ được nhiều hợp chất thực vật và chất chống oxy hóa khác nhau từ rất nhiều loại thực phẩm đa dạng. Việc ăn các loại trái cây và rau củ có màu sắc khác nhau, cùng với ngũ cốc nguyên hạt và các loại đậu, là cách tốt nhất để cơ thể tiếp cận với chất xơ, từ đó có thể hỗ trợ sức khỏe.”)</p>", "20": "<p>20 B</p><p>Câu hỏi: <i>Dark chocolate consumption could reduce medical spending in the future.</i></p><p>(Việc tiêu thụ sô-cô-la đen có thể giúp giảm chi phí y tế trong tương lai.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In 2013, the European Food Safety Authority approved the claim that cocoa flavanols help maintain normal blood pressure, which means that the cost involved in future medical treatment may be less than scientists previously predicted.</p><p>(Vào năm 2013, Cơ quan An toàn Thực phẩm châu Âu đã chấp thuận tuyên bố rằng flavanol trong ca cao giúp duy trì huyết áp bình thường, điều đó có nghĩa là chi phí cho việc điều trị y tế trong tương lai có thể thấp hơn so với những gì các nhà khoa học từng dự đoán trước đây.)</p>", "21": "<p>21 D</p><p>Câu hỏi: <i>Dark chocolate should not be considered a replacement for medicine.</i></p><p>(Không nên coi sô-cô-la đen là sự thay thế cho thuốc.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: results from the large European Prospective Investigation of Cancer, EPIC-Norfolk study suggest that the amount of flavanols that the average person in Europe or the United States consumes is unlikely to do much to reduce risk of cardiovascular disease compared with taking medicine.</p><p>(Kết quả từ nghiên cứu quy mô lớn của châu Âu mang tên European Prospective Investigation of Cancer (EPIC-Norfolk) cho thấy rằng lượng flavanol mà một người trung bình ở châu Âu hoặc Hoa Kỳ tiêu thụ khó có thể tạo ra nhiều tác dụng trong việc giảm nguy cơ bệnh tim mạch, nếu đem so với việc dùng thuốc.)</p>", "22": "<p>22 C</p><p>Câu hỏi: <i>The amount of cocoa required for health benefits remains uncertain.</i></p><p>(Lượng ca cao cần thiết để có lợi cho sức khỏe vẫn chưa chắc chắn.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Sesso and other researchers are investigating whether taking daily supplements of 600 mg of cocoa flavanols-not chocolate itself-reduces the risk for developing heart disease and stroke, as well as cancer. However, they have yet to determine how much people need to consume to reap benefits.</p><p>Sesso cùng với các nhà nghiên cứu khác đang tìm hiểu xem liệu việc dùng 600 mg flavanol từ ca cao mỗi ngày - không phải bản thân sô-cô-la - có giúp giảm nguy cơ mắc bệnh tim, đột quỵ cũng như ung thư hay không. Tuy nhiên, cho đến nay họ vẫn chưa xác định được chính xác mọi người cần tiêu thụ bao nhiêu để có thể nhận được lợi ích.</p>", "23": "<p>23 compounds</p><p>Câu hỏi: <i>The digestive process turns cocoa into less complex chemical ________.</i></p><p>(Quá trình tiêu hóa biến ca cao thành các hợp chất hóa học ______ hơn.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: During digestion, cocoa is broken down into smaller chemical compounds. Some research suggests that these compounds have anti-inflammatory and antioxidant properties and may help protect against cardiovascular disease, which affects both the heart and brain.</p><p>(Trong quá trình tiêu hóa, ca cao được phân giải thành những hợp chất hóa học nhỏ hơn. Một số nghiên cứu cho thấy những hợp chất này có đặc tính chống viêm và chống oxy hóa, đồng thời có thể giúp bảo vệ cơ thể khỏi bệnh tim mạch - căn bệnh ảnh hưởng đến cả tim và não.)</p>", "24": "<p>24 benefits</p><p>Câu hỏi: <i>The ________ would vary according to chocolate type with dark chocolate outperforming milk chocolate.</i></p><p>(________ sẽ khác nhau tùy loại sô-cô-la, trong đó sô-cô-la đen tốt hơn sô-cô-la sữa.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: ‘If we assume that any benefits from cocoa are attributable to its flavanol content, then dark chocolate should in theory confer greater benefits than milk chocolate.’</p><p>(“Nếu chúng ta cho rằng mọi lợi ích từ ca cao là nhờ vào hàm lượng flavanol của nó, thì về lý thuyết sô-cô-la đen sẽ mang lại lợi ích lớn hơn sô-cô-la sữa.”)</p>", "25": "<p>25 fats</p><p>Câu hỏi: <i>Dark chocolate should not be regarded as healthy due to its richness of calories and ________.</i></p><p>(Không nên coi sô-cô-la đen là thực phẩm tốt cho sức khỏe vì nó chứa nhiều calo và ________.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:  In the meantime, remember that chocolate products are typically high in calories and fats; therefore, Sesso says it’s best not to think of dark chocolate as a health food.</p><p>(Trong lúc này, hãy nhớ rằng các sản phẩm từ sô-cô-la thường chứa nhiều calo và chất béo; vì vậy, Sesso cho rằng tốt nhất không nên xem sô-cô-la đen là một loại thực phẩm tốt cho sức khỏe.)</p>", "26": "<p>26 fiber</p><p>Câu hỏi: <i>In Hultin’s view, dietary diversity is the best strategy for acquiring ________.</i></p><p>(Theo Hultin, đa dạng chế độ ăn là chiến lược tốt nhất để hấp thụ ________.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: ‘We get different phytochemicals and antioxidants from a wide variety of foods,’ Hultin says. ‘Including different colors of fruits, vegetables, whole grains and beans is the best way to gain access to fiber that could support health.’ </p><p>(Hultin nói: “Chúng ta nhận được nhiều loại hợp chất thực vật và chất chống oxy hóa khác nhau từ rất nhiều loại thực phẩm. Việc ăn các loại trái cây và rau củ có màu sắc khác nhau, cùng với ngũ cốc nguyên hạt và các loại đậu, là cách tốt nhất để cơ thể tiếp cận với chất xơ, thứ có thể hỗ trợ sức khỏe.”)</p>", "27": "<p>27 No</p><p>Câu hỏi: <i>Parents and siblings play equal roles in shaping people&#x27;s adult personalities</i>.</p><p>(Bố mẹ và anh chị em đóng vai trò ngang nhau trong việc hình thành tính cách của một người khi trưởng thành.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Our parents provide the genetic material and make powerful early role models, but even more influential in determining what kind of adult we will become are our brothers and sisters - our siblings</p><p>(Bố mẹ cho chúng ta vật chất di truyền và trở thành những hình mẫu mạnh mẽ đầu đời, nhưng những người có ảnh hưởng thậm chí còn lớn hơn trong việc quyết định chúng ta sẽ trở thành kiểu người trưởng thành như thế nào lại chính là anh chị em ruột của chúng ta.)</p>", "28": "<p>28 NG</p><p>Câu hỏi: <i>People&#x27;s first social relationships tend to be with siblings of their own gender</i></p><p>(Những mối quan hệ xã hội đầu tiên của con người thường là với anh/chị/em cùng giới tính.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: By turns enraging and lovable, familiar and mysterious, our brothers and sisters are the human beings who people our first social relationships.</p><p>(Khi thì khiến ta tức giận, khi thì đáng yêu; vừa quen thuộc lại vừa bí ẩn - anh chị em ruột của chúng ta là những con người tạo nên các mối quan hệ xã hội đầu tiên trong cuộc đời mỗi người.)</p><p>Giải thích: Bài chỉ nói mối quan hệ đầu tiên là với anh chị em, không nói cùng giới tính hay khác giới.</p>", "29": "<p>29 NG</p><p>Câu hỏi: <i>People&#x27;s relationships with their siblings tend to receive less attention when they marry</i></p><p>(Quan hệ giữa một người với anh/chị/em của họ thường nhận được ít sự chú ý hơn khi họ kết hôn.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: And a sibling relationship is the most enduring relationship many of us will ever have less emotionally intense than the bonds we form with our spouses and our own children if only because they started when we were so young.</p><p>(Và mối quan hệ giữa anh chị em là mối quan hệ lâu bền nhất mà nhiều người trong chúng ta từng có - ít mãnh liệt hơn về mặt cảm xúc so với mối liên kết chúng ta tạo dựng với vợ/chồng và con cái, nếu chỉ bởi vì mối quan hệ ấy đã bắt đầu từ khi chúng ta còn rất nhỏ.)</p><p>Giải thích: Câu hỏi nói: sau khi kết hôn thì quan hệ với anh chị em ít được chú ý hơn.Bài chỉ nói ít mãnh liệt hơn về cảm xúc, không nói về “được chú ý”.</p>", "30": "<p>30 Yes</p><p>Câu hỏi: <i>Parental &#x27;basking&#x27; is advantageous for later siblings</i></p><p>(Việc cha mẹ cảm thấy tự hào nhờ con cái thành công có lợi cho những người con sinh sau.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: It is clear that in turn this is associated with more positive parenting of younger children, who display fewer behavioural problems as a result.</p><p>(Rõ ràng điều này lại tiếp tục gắn liền với việc cha mẹ có cách nuôi dạy tích cực hơn đối với những đứa con nhỏ hơn, và kết quả là những đứa trẻ này có ít vấn đề về hành vi hơn.)</p>", "31": "<p>31 B</p><p>Câu hỏi: <i>What point does the writer make about birth order in the third paragraph?</i>A.    Its role is underestimated by parents.B.    It may shape the characteristics of adults.C.    Its importance decreases as children grow up.D.    It has more influence on personality than genetics.</p><p>(<i>Tác giả muốn nhấn mạnh điều gì về thứ tự sinh ở đoạn 3?</i>A.    Vai trò của nó bị cha mẹ đánh giá thấpB.    Nó có thể định hình đặc điểm của người trưởng thànhC.    Tầm quan trọng của nó giảm dần khi trẻ lớn lênD.    Nó ảnh hưởng đến tính cách nhiều hơn di truyền)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: It starts with birth order, which determines play roles: the firstborn leader, the middle-child mediator and the rebellious youngest. These are roles than can stick for life.</p><p>(Mọi chuyện bắt đầu từ thứ tự sinh, yếu tố quyết định vai trò khi chơi: con đầu là người dẫn dắt, con giữa là người hòa giải, còn con út thì nổi loạn. Đây là những vai trò có thể theo mỗi người suốt cả cuộc đời)</p>", "32": "<p>32 C</p><p>Câu hỏi: <i>What are we told about some of Claire Cartwright&#x27;s clients?</i>A.    Their parents treated them fairly.B.    They were treated harshly by their siblings.C.    Their perceptions of childhood may be inaccurate.D.    They have closer relations with their siblings as adults</p><p>(<i>Chúng ta được biết điều gì về một số khách hàng của Claire Cartwright?</i>A.    Bố mẹ đối xử công bằng với họB.    Họ bị anh chị em đối xử khắc nghiệtC.    Cách họ nhìn nhận tuổi thơ có thể không chính xácD.    Khi trưởng thành họ thân thiết hơn với anh chị em)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Clinical psychologist Claire Cartwright says she has clients who believe, and it might not have been true, that they were treated differently from their siblings, that one child in the family was preferred over others.</p><p>(Nhà tâm lý học lâm sàng Claire Cartwright cho biết bà có những khách hàng tin rằng - và điều đó có thể thực ra không đúng - rằng họ đã bị đối xử khác với anh chị em của mình, rằng có một đứa con trong gia đình được yêu thích hơn những đứa còn lại.)</p>", "33": "<p>33 C</p><p>Câu hỏi: <i>What is the writer&#x27;s main point about siblings in the fifth paragraph?</i>A.    Parents tend to repeat their own parents&#x27; mistakes.B.    Favored children are likely to make good leaders as adults.C.    Negative characteristics in children can become positive in adults.D.    Attention-seeking children are unlikely to please bosses in later life</p><p>(<i>Ý chính của tác giả về anh chị em ở đoạn 5 là gì?</i>A.    Cha mẹ thường lặp lại sai lầm của ông bàB.    Đứa con được ưu ái thường thành lãnh đạo tốtC.    Đặc điểm tiêu cực thời nhỏ có thể trở thành điểm mạnh khi lớnD.    Trẻ thích gây chú ý thường khó làm hài lòng sếp sau này)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: On the other hand, the sibling who is disruptive and annoying as a child may be able to reinterpret that role later, turning those attention-seeking characteristics into strengths like determination and leadership.</p><p>(Mặt khác, người anh/chị/em gây rối và khiến người khác khó chịu khi còn nhỏ có thể sau này diễn giải lại vai trò đó theo hướng khác, biến những đặc điểm thích thu hút sự chú ý ấy thành điểm mạnh như sự quyết tâm và khả năng lãnh đạo.)</p>", "34": "<p>34 D</p><p>Câu hỏi: <i>Which of the following best summarises the writer&#x27;s argument in the sixth paragraph?</i>A.    Many children have a favourite parent.B.    Parenting skills improve with later children.C.    Siblings are born with different personalities.D.    The family environment may change over time.</p><p>(<i>Ý nào tóm tắt tốt nhất lập luận ở đoạn 6?</i>A.    Nhiều đứa trẻ có một phụ huynh yêu thích hơnB.    Kỹ năng nuôi con tốt hơn với những đứa sinh sauC.    Anh chị em sinh ra với tính cách khác nhauD.    Môi trường gia đình có thể thay đổi theo thời gian)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: One answer is that, in fact, each sibling grows up in a different family, a unique micro-culture. For example, the firstborn is, for a while, an only child, and therefore has a completely different experience of the parents than those born later. The parents themselves are growing up too, weathering hardship or good fortune, so one sibling might experience stability and closeness while another might be raised in the midst of crisis.</p><p>(Một câu trả lời là trên thực tế, mỗi người con lớn lên trong một gia đình khác nhau, một “nền văn hóa nhỏ” riêng biệt. Ví dụ, con đầu trong một khoảng thời gian là con một, vì thế có trải nghiệm với cha mẹ hoàn toàn khác so với những người sinh sau. Bản thân cha mẹ cũng đang trưởng thành, trải qua khó khăn hoặc may mắn, nên một người con có thể trải nghiệm sự ổn định và gắn bó, trong khi người khác lại lớn lên giữa khủng hoảng.)</p>", "35": "<p>35 G</p><p>Câu hỏi: <i>Annette Henderson suggests that young children&#x27;s interactions with older siblings involve ________.</i></p><p>(Annette Henderson cho rằng sự tương tác của trẻ nhỏ với anh chị lớn hơn bao gồm ________.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: But younger children in turn benefit from unintentional instruction from their bigger brothers and sisters, acquiring entire phrases and an understanding of social concepts such as politeness</p><p>(Nhưng đến lượt mình, trẻ nhỏ lại được hưởng lợi từ sự chỉ dạy không chủ ý từ các anh chị lớn hơn, tiếp thu được cả những cụm từ hoàn chỉnh và hiểu biết về các khái niệm xã hội như phép lịch sự.)</p><p>=&gt; Đáp án: G - learning experiences (những trải nghiệm học hỏi)</p>", "36": "<p>36 B</p><p>Câu hỏi: <i>Also, a Cambridge study found that siblings still enjoy ________ even when they have a tendency to fight.</i></p><p>(Ngoài ra, một nghiên cứu của Đại học Cambridge cho thấy anh chị em vẫn thích ________, ngay cả khi họ thường có xu hướng cãi nhau hoặc đánh nhau.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Similarly, a Cambridge University study of 140 children found that even when there is a great deal of conflict, siblings will still create a rich world of play and make-believe that extends them developmentally.</p><p>(Tương tự, một nghiên cứu của Đại học Cambridge với 140 trẻ em cho thấy rằng ngay cả khi có rất nhiều xung đột, anh chị em vẫn tạo ra một thế giới phong phú của trò chơi và trí tưởng tượng, điều giúp các em phát triển hơn.)</p><p>=&gt; Đáp án: B - imaginative games ( trò chơi tưởng tượng)</p>", "37": "<p>37 F</p><p>Câu hỏi: <i>Research conducted in 2003 suggests that children develop ________ as a result of seeking attention.</i></p><p>(Nghiên cứu được thực hiện năm 2003 cho thấy trẻ em phát triển ________ do cố gắng thu hút sự chú ý.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:  A 2003 research paper studied adolescents from 185 families over two years, finding that those who changed, to differentiate themselves from their siblings, increased the amount of warmth they gained from parents, and also developed stronger personalities and a better sense of their own identity.</p><p>(Một nghiên cứu năm 2003 theo dõi thanh thiếu niên từ 185 gia đình trong hai năm, cho thấy rằng những em thay đổi để tạo sự khác biệt với anh chị em mình đã nhận được nhiều sự quan tâm hơn từ cha mẹ, đồng thời phát triển tính cách mạnh mẽ hơn và ý thức rõ hơn về bản sắc của bản thân.)</p><p>=&gt; Đáp án: F - greater individuality ( cá tính riêng mạnh hơn)</p>", "38": "<p>38 I</p><p>Câu hỏi: <i>Another factor is the trend for smaller families, which may mean that today&#x27;s siblings enjoy ________ as adults.</i></p><p>(Một yếu tố khác là xu hướng gia đình có ít con hơn, điều này có thể khiến anh chị em ngày nay có được ________ khi trưởng thành.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: This may be advantageous because siblings tend to know each other better and remain lifelong friends compared to children from bigger or more widely spaced families, who perhaps lose touch with one another after leaving home.</p><p>(Điều này có thể mang lại lợi ích vì anh chị em thường hiểu nhau rõ hơn và duy trì tình bạn suốt đời, so với những đứa trẻ trong gia đình đông con hơn hoặc cách tuổi nhau nhiều hơn — những người có thể dần mất liên lạc với nhau sau khi rời khỏi nhà.)</p><p>=&gt; Đáp án: I - closer relationships ( mối quan hệ gắn bó hơn)</p>", "39": "<p>39 K</p><p>Câu hỏi: <i>A 2010 American study linked having a sister with ________ among children aged 10–14.</i></p><p>(Một nghiên cứu của Mỹ năm 2010 cho thấy việc có chị/em gái có liên quan tới ________ ở trẻ từ 10 đến 14 tuổi.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Then there was a 2010 American study which found that having a sister, whether younger or older, meant that 10-to 14-year-olds were less likely to feel lonely, unloved, self-conscious or fearful.</p><p>(Sau đó là một nghiên cứu của Mỹ năm 2010 cho thấy rằng việc có một chị hoặc em gái, dù lớn hơn hay nhỏ hơn, khiến trẻ từ 10 đến 14 tuổi ít có khả năng cảm thấy cô đơn, không được yêu thương, mất tự tin hoặc sợ hãi hơn.)</p><p>=&gt; Đáp án: K - mental well-being ( sức khỏe tinh thần)</p>", "40": "<p>40 D</p><p>Câu hỏi: <i>Finally, having a sibling may promote ________ according to the same study.</i></p><p>(Cuối cùng, theo chính nghiên cứu đó, việc có anh chị em có thể thúc đẩy ________.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The same study found that having a loving sibling of either gender promoted good deeds, such as helping a neighbor around the house or helping other children at school</p><p>(Chính nghiên cứu đó cũng phát hiện rằng việc có một người anh/chị/em yêu thương mình, dù là nam hay nữ, giúp thúc đẩy những hành động tốt bụng, chẳng hạn như giúp hàng xóm việc nhà hoặc giúp đỡ những đứa trẻ khác ở trường.)</p><p>=&gt; Đáp án: D - generous behaviour (hành vi hào phóng).</p>"}, "transcriptSegments": {"1": [{"id": "r1-p1", "text": "Cranberries are among the few fruits native to North America that have been grown commercially for centuries. These small, crimson berries thrive only in very unique environmental conditions, particularly in soil that is both sandy and acidic. Such terrain lets water pass through easily while still retaining enough moisture for the plants’ shallow roots. Since ordinary farmland cannot provide this delicate balance, cranberries are generally cultivated in low-lying areas called bogs. These natural basins, bordered by gentle ridges, allow growers to regulate water levels accurately. This setup creates a growing environment quite different from that required by most other fruit crops.", "html": "<p>Cranberries are among the few fruits native to North America that have been grown commercially for centuries. These small, crimson berries thrive only in very unique environmental conditions, particularly in soil that is both sandy and acidic. Such terrain lets water pass through easily while still retaining enough moisture for the plants’ shallow roots. Since ordinary farmland cannot provide this delicate balance, cranberries are generally cultivated in low-lying areas called bogs. These natural basins, bordered by gentle ridges, allow growers to regulate water levels accurately. This setup creates a growing environment quite different from that required by most other fruit crops.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p2", "text": "Many bogs now used for cranberry farming were formed thousands of years ago when retreating glaciers carved deep hollows known as kettle ponds. Over time, these basins became lined with layers of sand and clay, producing a natural filtration system that keeps many pollutants out of the water. The clay bottom acts as a protective barrier, preventing harmful substances from entering the pond and preserving the clean water essential for healthy vines. Such geological conditions, combined with deliberate human control of water, have made kettle-pond sites especially well suited to this crop.", "html": "<p>Many bogs now used for cranberry farming were formed thousands of years ago when retreating glaciers carved deep hollows known as kettle ponds. Over time, these basins became lined with layers of sand and clay, producing a natural filtration system that keeps many pollutants out of the water. The clay bottom acts as a protective barrier, preventing harmful substances from entering the pond and preserving the clean water essential for healthy vines. Such geological conditions, combined with deliberate human control of water, have made kettle-pond sites especially well suited to this crop.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p3", "text": "Long before the arrival of European settlers, the Wampanoag people made practical use of the berry in several ways. The fruit’s sharp taste lent itself to preservation techniques; communities developed methods of drying and combining cranberries with other foods to extend their usefulness during months when fresh plants were scarce. These practices resulted in compact foodstuffs intended for consumption in colder seasons. In addition to dietary uses, the Wampanoag also employed the berry in first-aid traditions: crushed fruit was applied to sores and minor wounds, reflecting a practical knowledge of its cleansing properties.", "html": "<p>Long before the arrival of European settlers, the Wampanoag people made practical use of the berry in several ways. The fruit’s sharp taste lent itself to preservation techniques; communities developed methods of drying and combining cranberries with other foods to extend their usefulness during months when fresh plants were scarce. These practices resulted in compact foodstuffs intended for consumption in colder seasons. In addition to dietary uses, the Wampanoag also employed the berry in first-aid traditions: crushed fruit was applied to sores and minor wounds, reflecting a practical knowledge of its cleansing properties.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p4", "text": "When Europeans first arrived in the seventeenth century, they found cranberries in many coastal hollows and quickly took note of their usefulness. Rather than attempting to transplant European varieties, the newcomers adopted the native species already adapted to regional conditions. Colonists used the fruit in preserves and beverages and valued it for its nutritional contributions during winter voyages and inland shortages. Over time, cranberries were assimilated into colonial cookery and later became associated with holiday traditions in North America. In the early nineteenth century, the shift from gathering wild berries to planned cultivation accelerated thanks to local experimentation. One Massachusetts grower, Captain Henry Hall, observed that windblown sand reaching his beds improved fruit quality and yield. He began deliberately applying sand to his plots and found that the practice changed both soil texture and pest incidence for the better. Hall’s practice of controlling the land and surface materials was an important step toward systematic cranberry farming.", "html": "<p>When Europeans first arrived in the seventeenth century, they found cranberries in many coastal hollows and quickly took note of their usefulness. Rather than attempting to transplant European varieties, the newcomers adopted the native species already adapted to regional conditions. Colonists used the fruit in preserves and beverages and valued it for its nutritional contributions during winter voyages and inland shortages. Over time, cranberries were assimilated into colonial cookery and later became associated with holiday traditions in North America. In the early nineteenth century, the shift from gathering wild berries to planned cultivation accelerated thanks to local experimentation. One Massachusetts grower, Captain Henry Hall, observed that windblown sand reaching his beds improved fruit quality and yield. He began deliberately applying sand to his plots and found that the practice changed both soil texture and pest incidence for the better. Hall’s practice of controlling the land and surface materials was an important step toward systematic cranberry farming.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p5", "text": "Cranberry cultivation follows a seasonal routine that links each operation to weather patterns. In winter farmers often choose to flood the bogs, forming a protective layer that freezes and insulates the vines from extreme cold and drying winds. On the frozen surface, sand is sometimes scattered so that, when thawed, the particles work into the bed and improve overall drainage, encouraging fresh shoots to establish. To reduce disease risk and improve crop vigour, farmers also remove trees and scrub beside the bogs so that air can move through the site more freely and humidity is kept low.", "html": "<p>Cranberry cultivation follows a seasonal routine that links each operation to weather patterns. In winter farmers often choose to flood the bogs, forming a protective layer that freezes and insulates the vines from extreme cold and drying winds. On the frozen surface, sand is sometimes scattered so that, when thawed, the particles work into the bed and improve overall drainage, encouraging fresh shoots to establish. To reduce disease risk and improve crop vigour, farmers also remove trees and scrub beside the bogs so that air can move through the site more freely and humidity is kept low.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p6", "text": "With the coming of spring, the frozen cover is managed and water levels are adjusted; controlled water applications may be used at vulnerable times to shield budding shoots from sudden frosts. During this phase growers perform routine maintenance on channels, pumps and irrigation lines and take steps to reduce pest pressure before the plants enter full growth. By early summer the vines are active and the focus shifts toward ensuring the fruit matures evenly. Farmers inspect beds for any sign of weed emergence that would compete with the crop for nutrients and light, removing intruders promptly to protect potential yields.", "html": "<p>With the coming of spring, the frozen cover is managed and water levels are adjusted; controlled water applications may be used at vulnerable times to shield budding shoots from sudden frosts. During this phase growers perform routine maintenance on channels, pumps and irrigation lines and take steps to reduce pest pressure before the plants enter full growth. By early summer the vines are active and the focus shifts toward ensuring the fruit matures evenly. Farmers inspect beds for any sign of weed emergence that would compete with the crop for nutrients and light, removing intruders promptly to protect potential yields.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p7", "text": "As autumn nears, ripening fruit signals the approach of harvest. In many operations the bogs are flooded again so that the buoyant berries float and can be separated from the vines, easing collection. Although mechanical aids and modern equipment have changed some details of the work, the overall system continues to depend on balancing soil, water and human management. From the Wampanoag’s early practical uses to the innovations of later growers, cranberry culture remains rooted in seasonal attention and careful control of a unique landscape.", "html": "<p>As autumn nears, ripening fruit signals the approach of harvest. In many operations the bogs are flooded again so that the buoyant berries float and can be separated from the vines, easing collection. Although mechanical aids and modern equipment have changed some details of the work, the overall system continues to depend on balancing soil, water and human management. From the Wampanoag’s early practical uses to the innovations of later growers, cranberry culture remains rooted in seasonal attention and careful control of a unique landscape.</p>", "letter": null, "headingQuestion": null}], "2": [{"id": "r2-p1", "text": "A Dark chocolate is gaining a reputation as a heart-healthy food, and research suggests that there might be some substance behind those claims. Ginger Hultin, owner of Champagne Nutrition in Seattle and a spokesperson for the Academy of Nutrition and Dietetics says ‘Cocoa contains antioxidants in addition to magnesium, potassium, zinc, and iron. Plus, studies have shown that there could be some benefit to consuming chocolate or cocoa for the cardiovascular system, including potentially lowering blood pressure.’", "html": "<p><b>A</b> Dark chocolate is gaining a reputation as a heart-healthy food, and research suggests that there might be some substance behind those claims. Ginger Hultin, owner of Champagne Nutrition in Seattle and a spokesperson for the Academy of Nutrition and Dietetics says ‘Cocoa contains antioxidants in addition to magnesium, potassium, zinc, and iron. Plus, studies have shown that there could be some benefit to consuming chocolate or cocoa for the cardiovascular system, including potentially lowering blood pressure.’</p>", "letter": "A", "headingQuestion": null}, {"id": "r2-p2", "text": "B Dark chocolate’s health benefits come from its cocoa – specifically its cocoa flavanols. Flavanols are a type of polyphenol, and polyphenols are one group of phytochemicals. Many fruits and vegetables contain flavanols, but they are especially rich in tea, wine, and cocoa. During digestion, cocoa is broken down into smaller chemical compounds. Some research suggests that these compounds have anti-inflammatory and antioxidant properties and may help protect against cardiovascular disease, which affects both the heart and brain. For example, research has found that even two weeks of eating dark chocolate or other flavanol-rich cocoa products is better than a placebo for lowering blood pressure in people who already have high blood pressure, although not to normal levels. In 2013, the European Food Safety Authority approved the claim that cocoa flavanols help maintain normal blood pressure, which means that the cost involved in future medical treatment may be less than scientists previously predicted.", "html": "<p><b>B </b>Dark chocolate’s health benefits come from its cocoa – specifically its cocoa flavanols. Flavanols are a type of polyphenol, and polyphenols are one group of phytochemicals. Many fruits and vegetables contain flavanols, but they are especially rich in tea, wine, and cocoa. During digestion, cocoa is broken down into smaller chemical compounds. Some research suggests that these compounds have anti-inflammatory and antioxidant properties and may help protect against cardiovascular disease, which affects both the heart and brain. For example, research has found that even two weeks of eating dark chocolate or other flavanol-rich cocoa products is better than a placebo for lowering blood pressure in people who already have high blood pressure, although not to normal levels. In 2013, the European Food Safety Authority approved the claim that cocoa flavanols help maintain normal blood pressure, which means that the cost involved in future medical treatment may be less than scientists previously predicted.</p>", "letter": "B", "headingQuestion": null}, {"id": "r2-p3", "text": "C Researchers have also pointed out that people may digest cocoa differently. Variations in gut bacteria can influence how flavanols are processed and absorbed in the body. As a result, the health effects of cocoa may differ from person to person, depending on individual digestive systems and dietary habits.", "html": "<p><b>C</b> Researchers have also pointed out that people may digest cocoa differently. Variations in gut bacteria can influence how flavanols are processed and absorbed in the body. As a result, the health effects of cocoa may differ from person to person, depending on individual digestive systems and dietary habits.</p>", "letter": "C", "headingQuestion": null}, {"id": "r2-p4", "text": "D Data from the long-running Physicians’ Health Study suggests that chocolate intake is associated with a reduced risk of developing Type 2 diabetes in younger and normal-weight men. However, take those findings with a grain of salt, because they were based on a single question about average yearly intake of chocolate that didn’t ask what type of chocolate- white, milk, or dark-says Howard Sesso, an associate professor of preventive medicine at Brigham and Woman’s Hospital in Boston. ‘If we assume that any benefits from cocoa are attributable to its flavanol content, then dark chocolate should in theory confer greater benefits than milk chocolate.’ Sesso and other researchers are investigating whether taking daily supplements of 600 mg of cocoa flavanols-not chocolate itself-reduces the risk for developing heart disease and stroke, as well as cancer. However, they have yet to determine how much people need to consume to reap benefits", "html": "<p><b>D</b> Data from the long-running Physicians’ Health Study suggests that chocolate intake is associated with a reduced risk of developing Type 2 diabetes in younger and normal-weight men. However, take those findings with a grain of salt, because they were based on a single question about average yearly intake of chocolate that didn’t ask what type of chocolate- white, milk, or dark-says Howard Sesso, an associate professor of preventive medicine at Brigham and Woman’s Hospital in Boston. ‘If we assume that any benefits from cocoa are attributable to its flavanol content, then dark chocolate should in theory confer greater benefits than milk chocolate.’ Sesso and other researchers are investigating whether taking daily supplements of 600 mg of cocoa flavanols-not chocolate itself-reduces the risk for developing heart disease and stroke, as well as cancer. However, they have yet to determine how much people need to consume to reap benefits</p>", "letter": "D", "headingQuestion": null}, {"id": "r2-p5", "text": "E What does that mean for the average person who enjoys chocolate and hopes they’re getting some health benefit from it? Sadly, results from the large European Prospective Investigation of Cancer, EPIC-Norfolk study suggest that the amount of flavanols that the average person in Europe or the United States consumes is unlikely to do much to reduce risk of cardiovascular disease compared with taking medicine. The research also suggested that certain groups, particularly overweight individuals, may not receive the same protective effects from chocolate consumption as younger and normal-weight men.", "html": "<p><b>E</b> What does that mean for the average person who enjoys chocolate and hopes they’re getting some health benefit from it? Sadly, results from the large European Prospective Investigation of Cancer, EPIC-Norfolk study suggest that the amount of flavanols that the average person in Europe or the United States consumes is unlikely to do much to reduce risk of cardiovascular disease compared with taking medicine. The research also suggested that certain groups, particularly overweight individuals, may not receive the same protective effects from chocolate consumption as younger and normal-weight men.</p>", "letter": "E", "headingQuestion": null}, {"id": "r2-p6", "text": "F Even though cocoa is a key ingredient in milk and dark chocolate, you can’t really be sure how many flavanols you’re getting. ‘Product packaging does not specify amounts of cocoa flavanols, only percent cacao,’ Sesso says. ‘Variable processing of the cocoa bean makes it difficult to equate percent cacao with cocoa flavanol content.’ White chocolate contains no cocoa solids, milk chocolate contains relatively small amounts of cocoa, while dark chocolate contains a much higher percentage of cocoa. Cocoa may also appear in the form of cocoa powder, cocoa butter, or concentrated cocoa extracts.", "html": "<p><b>F</b> Even though cocoa is a key ingredient in milk and dark chocolate, you can’t really be sure how many flavanols you’re getting. ‘Product packaging does not specify amounts of cocoa flavanols, only percent cacao,’ Sesso says. ‘Variable processing of the cocoa bean makes it difficult to equate percent cacao with cocoa flavanol content.’ White chocolate contains no cocoa solids, milk chocolate contains relatively small amounts of cocoa, while dark chocolate contains a much higher percentage of cocoa. Cocoa may also appear in the form of cocoa powder, cocoa butter, or concentrated cocoa extracts.</p>", "letter": "F", "headingQuestion": null}, {"id": "r2-p7", "text": "G In the meantime, remember that chocolate products are typically high in calories and fats; therefore, Sesso says it’s best not to think of dark chocolate as a health food. ‘Moderation is key; if someone enjoys eating chocolate, it should be done in moderation along with other foods.’ So for now, it’s best not to put all your flavanol eggs in a dark chocolate basket. ‘We get different phytochemicals and antioxidants from a wide variety of foods,’ Hultin says. ‘Including different colors of fruits, vegetables, whole grains and beans is the best way to gain access to fiber that could support health.’ That said, she does recommend enjoying a bit of chocolate or cocoa. ‘I put cocoa powder in my smoothies for an added boost of flavor, nutrients and antioxidants.’", "html": "<p><b>G</b> In the meantime, remember that chocolate products are typically high in calories and fats; therefore, Sesso says it’s best not to think of dark chocolate as a health food. ‘Moderation is key; if someone enjoys eating chocolate, it should be done in moderation along with other foods.’ So for now, it’s best not to put all your flavanol eggs in a dark chocolate basket. ‘We get different phytochemicals and antioxidants from a wide variety of foods,’ Hultin says. ‘Including different colors of fruits, vegetables, whole grains and beans is the best way to gain access to fiber that could support health.’ That said, she does recommend enjoying a bit of chocolate or cocoa. ‘I put cocoa powder in my smoothies for an added boost of flavor, nutrients and antioxidants.’</p>", "letter": "G", "headingQuestion": null}], "3": [{"id": "r3-p1", "text": "We can choose our friends, the saying goes, but we cannot choose our family of origin. Our parents provide the genetic material and make powerful early role models, but even more influential in determining what kind of adult we will become are our brothers and sisters - our siblings. They occupy a position of unique intimacy in our lives and cast a longer shadow than many recognize or are prepared to acknowledge. By turns enraging and lovable, familiar and mysterious, our brothers and sisters are the human beings who people our first social relationships. And a sibling relationship is the most enduring relationship many of us will ever have, less emotionally intense than the bonds we form with our spouses and our own children if only because they started when we were so young.", "html": "<p>We can choose our friends, the saying goes, but we cannot choose our family of origin. Our parents provide the genetic material and make powerful early role models, but even more influential in determining what kind of adult we will become are our brothers and sisters - our siblings. They occupy a position of unique intimacy in our lives and cast a longer shadow than many recognize or are prepared to acknowledge. By turns enraging and lovable, familiar and mysterious, our brothers and sisters are the human beings who people our first social relationships. And a sibling relationship is the most enduring relationship many of us will ever have, less emotionally intense than the bonds we form with our spouses and our own children if only because they started when we were so young.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p2", "text": "Surprising new research by Dr Gene Brody found that having older children who do well in school and are well liked by other children leads to parental 'basking' - increasing mothers' self-esteem. It is clear that in turn this is associated with more positive parenting of younger children, who display fewer behavioural problems as a result. Conversely, parents who get a difficult first child may in turn experience a negative spiral of household tension.", "html": "<p>Surprising new research by Dr Gene Brody found that having older children who do well in school and are well liked by other children leads to parental &#x27;basking&#x27; - increasing mothers&#x27; self-esteem. It is clear that in turn this is associated with more positive parenting of younger children, who display fewer behavioural problems as a result. Conversely, parents who get a difficult first child may in turn experience a negative spiral of household tension.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p3", "text": "International sports star Piri Weepu is a rugby hard man, but at least some of his tough temperament was forged long ago in the family home. His older brother Billy started rugby-tackling little Piri when he was just four - to 'harden him up'. It seemed to work: Piri followed his brother in playing for the under-sevens league before he even started school. There are as many such stories as there are families: in the formative hothouse of the family, siblings interact in complex ways with the powerful force fields of parents, genetics and personality already at work. It starts with birth order, which determines play roles: the firstborn leader, the middle-child mediator and the rebellious youngest. These are roles than can stick for life.", "html": "<p>International sports star Piri Weepu is a rugby hard man, but at least some of his tough temperament was forged long ago in the family home. His older brother Billy started rugby-tackling little Piri when he was just four - to &#x27;harden him up&#x27;. It seemed to work: Piri followed his brother in playing for the under-sevens league before he even started school. There are as many such stories as there are families: in the formative hothouse of the family, siblings interact in complex ways with the powerful force fields of parents, genetics and personality already at work. It starts with birth order, which determines play roles: the firstborn leader, the middle-child mediator and the rebellious youngest. These are roles than can stick for life.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p4", "text": "Clinical psychologist Claire Cartwright says she has clients who believe, and it might not have been true, that they were treated differently from their siblings, that one child in the family was preferred over others. They are quite convinced that the parental judgments on them all those years ago were harsher, and that they were the ones who always got into trouble. Later, in the workplace, such a person might be particularly defensive, and so behave in a way more prone to attracting harsh judgements.", "html": "<p>Clinical psychologist Claire Cartwright says she has clients who believe, and it might not have been true, that they were treated differently from their siblings, that one child in the family was preferred over others. They are quite convinced that the parental judgments on them all those years ago were harsher, and that they were the ones who always got into trouble. Later, in the workplace, such a person might be particularly defensive, and so behave in a way more prone to attracting harsh judgements.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p5", "text": "However, the research shows that being Mummy or Daddy's favourite has its own traps. If you were the easy-going, co-operative child at home, you probably excelled at pleasing parents and, later, bosses. But you might, as an adult, find it hard to be assertive with authority figures and lack direction. On the other hand, the sibling who is disruptive and annoying as a child may be able to reinterpret that role later, turning those attention-seeking characteristics into strengths like determination and leadership.", "html": "<p>However, the research shows that being Mummy or Daddy&#x27;s favourite has its own traps. If you were the easy-going, co-operative child at home, you probably excelled at pleasing parents and, later, bosses. But you might, as an adult, find it hard to be assertive with authority figures and lack direction. On the other hand, the sibling who is disruptive and annoying as a child may be able to reinterpret that role later, turning those attention-seeking characteristics into strengths like determination and leadership.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p6", "text": "How is it that full siblings, despite sharing DNA, can turn out so differently? One answer is that, in fact, each sibling grows up in a different family, a unique micro-culture. For example, the firstborn is, for a while, an only child, and therefore has a completely different experience of the parents than those born later. The parents themselves are growing up too, weathering hardship or good fortune, so one sibling might experience stability and closeness while another might be raised in the midst of crisis.", "html": "<p>How is it that full siblings, despite sharing DNA, can turn out so differently? One answer is that, in fact, each sibling grows up in a different family, a unique micro-culture. For example, the firstborn is, for a while, an only child, and therefore has a completely different experience of the parents than those born later. The parents themselves are growing up too, weathering hardship or good fortune, so one sibling might experience stability and closeness while another might be raised in the midst of crisis.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p7", "text": "Of course, there are many positive aspects of sibling relationships. Annette Henderson, a lecturer in psychology, says firstborn children learn vocabulary more quickly than their siblings because they are not competing to spend one-on-one time with parents. But younger children in turn benefit from unintentional instruction from their bigger brothers and sisters, acquiring entire phrases and an understanding of social concepts such as politeness. Similarly, a Cambridge University study of 140 children found that even when there is a great deal of conflict, siblings will still create a rich world of play and make-believe that extends them developmentally. Love-hate relationships were common among the children, but even those who fought the most had as many positive interactions as the other sibling pairs. It is also true that children compete for parental attention by making themselves different from their brothers and sisters, particularly if they are close in age. A 2003 research paper studied adolescents from 185 families over two years, finding that those who changed, to differentiate themselves from their siblings, increased the amount of warmth they gained from parents, and also developed stronger personalities and a better sense of their own identity.", "html": "<p>Of course, there are many positive aspects of sibling relationships. Annette Henderson, a lecturer in psychology, says firstborn children learn vocabulary more quickly than their siblings because they are not competing to spend one-on-one time with parents. But younger children in turn benefit from unintentional instruction from their bigger brothers and sisters, acquiring entire phrases and an understanding of social concepts such as politeness. Similarly, a Cambridge University study of 140 children found that even when there is a great deal of conflict, siblings will still create a rich world of play and make-believe that extends them developmentally. Love-hate relationships were common among the children, but even those who fought the most had as many positive interactions as the other sibling pairs. It is also true that children compete for parental attention by making themselves different from their brothers and sisters, particularly if they are close in age. A 2003 research paper studied adolescents from 185 families over two years, finding that those who changed, to differentiate themselves from their siblings, increased the amount of warmth they gained from parents, and also developed stronger personalities and a better sense of their own identity.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p8", "text": "Another consideration is that many families today are smaller and more intimate than their historical counterparts. This may be advantageous because siblings tend to know each other better and remain lifelong friends compared to children from bigger or more widely spaced families, who perhaps lose touch with one another after leaving home. Then there was a 2010 American study which found that having a sister, whether younger or older, meant that 10-to 14-year-olds were less likely to feel lonely, unloved, self-conscious or fearful. The same study found that having a loving sibling of either gender promoted good deeds, such as helping a neighbor around the house or helping other children at school.", "html": "<p>Another consideration is that many families today are smaller and more intimate than their historical counterparts. This may be advantageous because siblings tend to know each other better and remain lifelong friends compared to children from bigger or more widely spaced families, who perhaps lose touch with one another after leaving home. Then there was a 2010 American study which found that having a sister, whether younger or older, meant that 10-to 14-year-olds were less likely to feel lonely, unloved, self-conscious or fearful. The same study found that having a loving sibling of either gender promoted good deeds, such as helping a neighbor around the house or helping other children at school.</p>", "letter": null, "headingQuestion": null}]}, "transcripts": {"1": "<p>Cranberries are among the few fruits native to North America that have been grown commercially for centuries. These small, crimson berries thrive only in very unique environmental conditions, particularly in soil that is both sandy and acidic. Such terrain lets water pass through easily while still retaining enough moisture for the plants’ shallow roots. Since ordinary farmland cannot provide this delicate balance, cranberries are generally cultivated in low-lying areas called bogs. These natural basins, bordered by gentle ridges, allow growers to regulate water levels accurately. This setup creates a growing environment quite different from that required by most other fruit crops.</p><p>Many bogs now used for cranberry farming were formed thousands of years ago when retreating glaciers carved deep hollows known as kettle ponds. Over time, these basins became lined with layers of sand and clay, producing a natural filtration system that keeps many pollutants out of the water. The clay bottom acts as a protective barrier, preventing harmful substances from entering the pond and preserving the clean water essential for healthy vines. Such geological conditions, combined with deliberate human control of water, have made kettle-pond sites especially well suited to this crop.</p><p>Long before the arrival of European settlers, the Wampanoag people made practical use of the berry in several ways. The fruit’s sharp taste lent itself to preservation techniques; communities developed methods of drying and combining cranberries with other foods to extend their usefulness during months when fresh plants were scarce. These practices resulted in compact foodstuffs intended for consumption in colder seasons. In addition to dietary uses, the Wampanoag also employed the berry in first-aid traditions: crushed fruit was applied to sores and minor wounds, reflecting a practical knowledge of its cleansing properties.</p><p>When Europeans first arrived in the seventeenth century, they found cranberries in many coastal hollows and quickly took note of their usefulness. Rather than attempting to transplant European varieties, the newcomers adopted the native species already adapted to regional conditions. Colonists used the fruit in preserves and beverages and valued it for its nutritional contributions during winter voyages and inland shortages. Over time, cranberries were assimilated into colonial cookery and later became associated with holiday traditions in North America. In the early nineteenth century, the shift from gathering wild berries to planned cultivation accelerated thanks to local experimentation. One Massachusetts grower, Captain Henry Hall, observed that windblown sand reaching his beds improved fruit quality and yield. He began deliberately applying sand to his plots and found that the practice changed both soil texture and pest incidence for the better. Hall’s practice of controlling the land and surface materials was an important step toward systematic cranberry farming.</p><p>Cranberry cultivation follows a seasonal routine that links each operation to weather patterns. In winter farmers often choose to flood the bogs, forming a protective layer that freezes and insulates the vines from extreme cold and drying winds. On the frozen surface, sand is sometimes scattered so that, when thawed, the particles work into the bed and improve overall drainage, encouraging fresh shoots to establish. To reduce disease risk and improve crop vigour, farmers also remove trees and scrub beside the bogs so that air can move through the site more freely and humidity is kept low.</p><p>With the coming of spring, the frozen cover is managed and water levels are adjusted; controlled water applications may be used at vulnerable times to shield budding shoots from sudden frosts. During this phase growers perform routine maintenance on channels, pumps and irrigation lines and take steps to reduce pest pressure before the plants enter full growth. By early summer the vines are active and the focus shifts toward ensuring the fruit matures evenly. Farmers inspect beds for any sign of weed emergence that would compete with the crop for nutrients and light, removing intruders promptly to protect potential yields.</p><p>As autumn nears, ripening fruit signals the approach of harvest. In many operations the bogs are flooded again so that the buoyant berries float and can be separated from the vines, easing collection. Although mechanical aids and modern equipment have changed some details of the work, the overall system continues to depend on balancing soil, water and human management. From the Wampanoag’s early practical uses to the innovations of later growers, cranberry culture remains rooted in seasonal attention and careful control of a unique landscape.</p>", "2": "<p><b>A</b> Dark chocolate is gaining a reputation as a heart-healthy food, and research suggests that there might be some substance behind those claims. Ginger Hultin, owner of Champagne Nutrition in Seattle and a spokesperson for the Academy of Nutrition and Dietetics says ‘Cocoa contains antioxidants in addition to magnesium, potassium, zinc, and iron. Plus, studies have shown that there could be some benefit to consuming chocolate or cocoa for the cardiovascular system, including potentially lowering blood pressure.’</p><p><b>B </b>Dark chocolate’s health benefits come from its cocoa – specifically its cocoa flavanols. Flavanols are a type of polyphenol, and polyphenols are one group of phytochemicals. Many fruits and vegetables contain flavanols, but they are especially rich in tea, wine, and cocoa. During digestion, cocoa is broken down into smaller chemical compounds. Some research suggests that these compounds have anti-inflammatory and antioxidant properties and may help protect against cardiovascular disease, which affects both the heart and brain. For example, research has found that even two weeks of eating dark chocolate or other flavanol-rich cocoa products is better than a placebo for lowering blood pressure in people who already have high blood pressure, although not to normal levels. In 2013, the European Food Safety Authority approved the claim that cocoa flavanols help maintain normal blood pressure, which means that the cost involved in future medical treatment may be less than scientists previously predicted.</p><p><b>C</b> Researchers have also pointed out that people may digest cocoa differently. Variations in gut bacteria can influence how flavanols are processed and absorbed in the body. As a result, the health effects of cocoa may differ from person to person, depending on individual digestive systems and dietary habits.</p><p><b>D</b> Data from the long-running Physicians’ Health Study suggests that chocolate intake is associated with a reduced risk of developing Type 2 diabetes in younger and normal-weight men. However, take those findings with a grain of salt, because they were based on a single question about average yearly intake of chocolate that didn’t ask what type of chocolate- white, milk, or dark-says Howard Sesso, an associate professor of preventive medicine at Brigham and Woman’s Hospital in Boston. ‘If we assume that any benefits from cocoa are attributable to its flavanol content, then dark chocolate should in theory confer greater benefits than milk chocolate.’ Sesso and other researchers are investigating whether taking daily supplements of 600 mg of cocoa flavanols-not chocolate itself-reduces the risk for developing heart disease and stroke, as well as cancer. However, they have yet to determine how much people need to consume to reap benefits</p><p><b>E</b> What does that mean for the average person who enjoys chocolate and hopes they’re getting some health benefit from it? Sadly, results from the large European Prospective Investigation of Cancer, EPIC-Norfolk study suggest that the amount of flavanols that the average person in Europe or the United States consumes is unlikely to do much to reduce risk of cardiovascular disease compared with taking medicine. The research also suggested that certain groups, particularly overweight individuals, may not receive the same protective effects from chocolate consumption as younger and normal-weight men.</p><p><b>F</b> Even though cocoa is a key ingredient in milk and dark chocolate, you can’t really be sure how many flavanols you’re getting. ‘Product packaging does not specify amounts of cocoa flavanols, only percent cacao,’ Sesso says. ‘Variable processing of the cocoa bean makes it difficult to equate percent cacao with cocoa flavanol content.’ White chocolate contains no cocoa solids, milk chocolate contains relatively small amounts of cocoa, while dark chocolate contains a much higher percentage of cocoa. Cocoa may also appear in the form of cocoa powder, cocoa butter, or concentrated cocoa extracts.</p><p><b>G</b> In the meantime, remember that chocolate products are typically high in calories and fats; therefore, Sesso says it’s best not to think of dark chocolate as a health food. ‘Moderation is key; if someone enjoys eating chocolate, it should be done in moderation along with other foods.’ So for now, it’s best not to put all your flavanol eggs in a dark chocolate basket. ‘We get different phytochemicals and antioxidants from a wide variety of foods,’ Hultin says. ‘Including different colors of fruits, vegetables, whole grains and beans is the best way to gain access to fiber that could support health.’ That said, she does recommend enjoying a bit of chocolate or cocoa. ‘I put cocoa powder in my smoothies for an added boost of flavor, nutrients and antioxidants.’</p>", "3": "<p>We can choose our friends, the saying goes, but we cannot choose our family of origin. Our parents provide the genetic material and make powerful early role models, but even more influential in determining what kind of adult we will become are our brothers and sisters - our siblings. They occupy a position of unique intimacy in our lives and cast a longer shadow than many recognize or are prepared to acknowledge. By turns enraging and lovable, familiar and mysterious, our brothers and sisters are the human beings who people our first social relationships. And a sibling relationship is the most enduring relationship many of us will ever have, less emotionally intense than the bonds we form with our spouses and our own children if only because they started when we were so young.</p><p>Surprising new research by Dr Gene Brody found that having older children who do well in school and are well liked by other children leads to parental &#x27;basking&#x27; - increasing mothers&#x27; self-esteem. It is clear that in turn this is associated with more positive parenting of younger children, who display fewer behavioural problems as a result. Conversely, parents who get a difficult first child may in turn experience a negative spiral of household tension.</p><p>International sports star Piri Weepu is a rugby hard man, but at least some of his tough temperament was forged long ago in the family home. His older brother Billy started rugby-tackling little Piri when he was just four - to &#x27;harden him up&#x27;. It seemed to work: Piri followed his brother in playing for the under-sevens league before he even started school. There are as many such stories as there are families: in the formative hothouse of the family, siblings interact in complex ways with the powerful force fields of parents, genetics and personality already at work. It starts with birth order, which determines play roles: the firstborn leader, the middle-child mediator and the rebellious youngest. These are roles than can stick for life.</p><p>Clinical psychologist Claire Cartwright says she has clients who believe, and it might not have been true, that they were treated differently from their siblings, that one child in the family was preferred over others. They are quite convinced that the parental judgments on them all those years ago were harsher, and that they were the ones who always got into trouble. Later, in the workplace, such a person might be particularly defensive, and so behave in a way more prone to attracting harsh judgements.</p><p>However, the research shows that being Mummy or Daddy&#x27;s favourite has its own traps. If you were the easy-going, co-operative child at home, you probably excelled at pleasing parents and, later, bosses. But you might, as an adult, find it hard to be assertive with authority figures and lack direction. On the other hand, the sibling who is disruptive and annoying as a child may be able to reinterpret that role later, turning those attention-seeking characteristics into strengths like determination and leadership.</p><p>How is it that full siblings, despite sharing DNA, can turn out so differently? One answer is that, in fact, each sibling grows up in a different family, a unique micro-culture. For example, the firstborn is, for a while, an only child, and therefore has a completely different experience of the parents than those born later. The parents themselves are growing up too, weathering hardship or good fortune, so one sibling might experience stability and closeness while another might be raised in the midst of crisis.</p><p>Of course, there are many positive aspects of sibling relationships. Annette Henderson, a lecturer in psychology, says firstborn children learn vocabulary more quickly than their siblings because they are not competing to spend one-on-one time with parents. But younger children in turn benefit from unintentional instruction from their bigger brothers and sisters, acquiring entire phrases and an understanding of social concepts such as politeness. Similarly, a Cambridge University study of 140 children found that even when there is a great deal of conflict, siblings will still create a rich world of play and make-believe that extends them developmentally. Love-hate relationships were common among the children, but even those who fought the most had as many positive interactions as the other sibling pairs. It is also true that children compete for parental attention by making themselves different from their brothers and sisters, particularly if they are close in age. A 2003 research paper studied adolescents from 185 families over two years, finding that those who changed, to differentiate themselves from their siblings, increased the amount of warmth they gained from parents, and also developed stronger personalities and a better sense of their own identity.</p><p>Another consideration is that many families today are smaller and more intimate than their historical counterparts. This may be advantageous because siblings tend to know each other better and remain lifelong friends compared to children from bigger or more widely spaced families, who perhaps lose touch with one another after leaving home. Then there was a 2010 American study which found that having a sister, whether younger or older, meant that 10-to 14-year-olds were less likely to feel lonely, unloved, self-conscious or fearful. The same study found that having a loving sibling of either gender promoted good deeds, such as helping a neighbor around the house or helping other children at school.</p>"}, "questionSegments": {"1": ["r1-p1"], "2": ["r1-p2"], "3": ["r1-p3"], "4": ["r1-p3"], "5": ["r1-p4"], "6": ["r1-p4"], "7": ["r1-p4"], "8": ["r1-p5"], "9": ["r1-p5"], "10": ["r1-p5"], "11": ["r1-p6"], "12": ["r1-p6"], "13": ["r1-p6"], "14": ["r2-p6"], "15": ["r2-p2"], "16": ["r2-p5"], "17": ["r2-p7"], "18": ["r2-p3"], "19": ["r2-p7"], "20": ["r2-p2"], "21": ["r2-p5"], "22": ["r2-p4"], "23": ["r2-p2"], "24": ["r2-p4"], "25": ["r2-p7"], "26": ["r2-p7"], "27": ["r3-p1"], "28": ["r3-p1"], "29": ["r3-p1"], "30": ["r3-p2"], "31": ["r3-p3"], "32": ["r3-p4"], "33": ["r3-p5"], "34": ["r3-p6"], "35": ["r3-p7"], "36": ["r3-p7"], "37": ["r3-p7"], "38": ["r3-p8"], "39": ["r3-p8"], "40": ["r3-p8"]}, "headingsBySection": {}, "grading": {"pairs": [], "sets": []}, "groups": [[1, 13], [14, 26], [27, 40]], "questionTypes": {"1": "boolean", "2": "boolean", "3": "boolean", "4": "boolean", "5": "boolean", "6": "boolean", "7": "boolean", "8": "gap", "9": "gap", "10": "gap", "11": "gap", "12": "gap", "13": "gap", "14": "matching", "15": "matching", "16": "matching", "17": "matching", "18": "matching", "19": "matching", "20": "matching", "21": "matching", "22": "matching", "23": "gap", "24": "gap", "25": "gap", "26": "gap", "27": "boolean", "28": "boolean", "29": "boolean", "30": "boolean", "31": "single", "32": "single", "33": "single", "34": "single", "35": "matching", "36": "matching", "37": "matching", "38": "matching", "39": "matching", "40": "matching"}, "sourceAnswerKey": {"1": ["TRUE"], "2": ["TRUE"], "3": ["FALSE"], "4": ["TRUE"], "5": ["NOT GIVEN"], "6": ["NOT GIVEN"], "7": ["NOT GIVEN"], "8": ["flood"], "9": ["drainage"], "10": ["air"], "11": ["water"], "12": ["maintenance"], "13": ["weed"], "14": ["F"], "15": ["B"], "16": ["E"], "17": ["G"], "18": ["C"], "19": ["A"], "20": ["B"], "21": ["D"], "22": ["C"], "23": ["compounds"], "24": ["benefits"], "25": ["fats"], "26": ["fiber"], "27": ["NO"], "28": ["NOT GIVEN"], "29": ["NOT GIVEN"], "30": ["YES"], "31": ["B"], "32": ["C"], "33": ["C"], "34": ["D"], "35": ["G"], "36": ["B"], "37": ["F"], "38": ["I"], "39": ["K"], "40": ["D"]}, "sourceNotes": [], "hasAnswerKey": true};
